	('838e6c1b-3519-4bb7-a1b1-a3da3fe346de', '2025-06-15 03:57:58.268453+00', 'Dell UltraSharp 4K Monitor 27 inch', 'Professional 4K monitor perfect for development and design work. Like new condition, includes original stand and cables.', 'product', 450, 'like-new', '{https://images.unsplash.com/photo-1527443224154-c4a3942d3acf?w=600}', '32c4cdb7-1c92-414a-b772-15b8a0ef05b6', 'Castlegar, BC', '{monitor,dell,display}', 'published', false, '{"email": "marcus@example.com", "phone": "+1-250-555-0102"}'),
