INSERT INTO "public"."news" ("id", "created_at", "title", "slug", "content", "excerpt", "hero_image", "hero_image_alt", "publish_date", "status", "tags", "author_id", "featured") VALUES
	('079d8986-ee90-47ad-846d-e7bd6d8a72bb', '2025-06-15 03:08:05.243059+00', 'Nelson Tech Community Hits 500 Members', 'nelson-tech-500-members', 'We are thrilled to announce that the Nelson Tech Community has reached an incredible milestone of 500 active members! This achievement represents the growing strength of our local tech ecosystem.', 'Our growing community celebrates reaching 500 active members.', 'https://images.unsplash.com/photo-1522202176988-66273c2fd55f?w=800', NULL, '2025-01-10', 'published', '{community,milestone,growth}', '32c4cdb7-1c92-414a-b772-15b8a0ef05b6', true),
	('30f9d5f7-50bf-4e12-9293-f9bc518da170', '2025-06-15 03:08:05.243059+00', 'New Partnership with Selkirk College', 'selkirk-college-partnership', 'We are excited to announce a groundbreaking partnership between the Nelson Tech Community and Selkirk College that will bridge the gap between education and industry.', 'Exciting collaboration with Selkirk College for student mentorship.', 'https://images.unsplash.com/photo-1523240795612-9a054b0db644?w=800', NULL, '2025-01-05', 'published', '{education,partnership,students}', '32c4cdb7-1c92-414a-b772-15b8a0ef05b6', false),
	('68afbf1b-1ae0-4e53-a352-fa70542811f6', '2025-06-15 03:08:05.243059+00', 'Tech Career Fair Success', 'tech-career-fair-2025', 'Last week tech career fair was a huge success with over 200 attendees and 15 companies participating.', 'Career fair connects local talent with opportunities.', 'https://images.unsplash.com/photo-1559136555-9303baea8ebd?w=800', NULL, '2025-01-15', 'published', '{careers,events,jobs}', '32c4cdb7-1c92-414a-b772-15b8a0ef05b6', true);
